<?php
declare(strict_types=1);namespace Pam\Native\Observability;use RuntimeException;final class CurlTelemetryTransport implements TelemetryTransport{public function send(string$endpoint,string$body,array$headers,int$timeoutMillis):void{if(!extension_loaded('curl'))throw new RuntimeException('The curl extension is required by CurlTelemetryTransport.');$handle=curl_init($endpoint);if($handle===false)throw new RuntimeException('Could not initialize cURL.');curl_setopt_array($handle,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$body,CURLOPT_HTTPHEADER=>array_map(fn($k,$v)=>$k.': '.$v,array_keys($headers),$headers),CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT_MS=>$timeoutMillis,CURLOPT_TIMEOUT_MS=>$timeoutMillis,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS]);$result=curl_exec($handle);$status=(int)curl_getinfo($handle,CURLINFO_RESPONSE_CODE);$error=curl_error($handle);curl_close($handle);if($result===false||$status<200||$status>=300)throw new RuntimeException('Telemetry export failed: '.($error?:'HTTP '.$status));}}
